'use strict';
(()=>{
 const D=window.GameData,K=window.CharacterData,P=window.SkillPresentation,esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const goals=[{id:'trait',name:'특성의 완성',desc:'특성 2단계를 갖춘 덱으로 승리하고 해당 특성을 실제 발동하세요.'},{id:'policy',name:'두 가지 운용',desc:'공격·보호 방침으로 각각 교전에서 승리하세요. 서로 다른 상대여도 됩니다.'},{id:'reward',name:'새로운 힘',desc:'원정 전용 보상 카드를 편성하고 피해·회복·보호 등 실제 효과를 확인하세요.'}];
 const fields=['damage','healed','shield','blocks','shared','moved'],labels={damage:'피해',healed:'회복',shield:'보호막 흡수',blocks:'차단',shared:'피해 분담',moved:'이동 인원'};
 const fresh=()=>({version:1,traits:[],policies:[],rewards:[],moments:[]});
 const rewardKeys=()=>K.playableCharacters().flatMap(c=>c.reward),sceneKeys=()=>Object.keys(D.cards).filter(k=>['signature','ultimate'].includes(P.profile(k).tier));
 const unique=(a,allowed,max)=>Array.isArray(a)&&a.length<=max&&new Set(a).size===a.length&&a.every(k=>allowed.includes(k));
 const sceneOwner=key=>K.owner(key)?.id||Object.entries(window.UltimateData?.profiles||{}).find(([,p])=>p.key===key)?.[0];
 function valid(x){return !!(x&&x.version===1&&Object.keys(x).every(k=>['version','traits','policies','rewards','moments'].includes(k))&&unique(x.traits,Object.keys(window.CardTraits.traits),3)&&unique(x.policies,['attack','protect'],2)&&unique(x.rewards,rewardKeys(),32)&&Array.isArray(x.moments)&&x.moments.length<=12&&new Set(x.moments.map(m=>m?.key)).size===x.moments.length&&x.moments.every(m=>m&&Object.keys(m).every(k=>['key','characterId','kind','amount','uses','encounter'].includes(k))&&sceneKeys().includes(m.key)&&sceneOwner(m.key)===m.characterId&&fields.includes(m.kind)&&Number.isFinite(m.amount)&&m.amount>0&&m.amount<=1e7&&Number.isSafeInteger(m.uses)&&m.uses>0&&m.uses<=10000&&typeof m.encounter==='string'&&m.encounter.length<=80));}
 function done(x,id){return id==='trait'?x.traits.length>0:id==='policy'?x.policies.length===2:x.rewards.length>0;}
 function effective(row){return fields.filter(k=>Number.isFinite(row?.[k])&&row[k]>0).sort((a,b)=>row[b]-row[a])[0]||null;}
 function scenes(result){if(!result?.insights?.rows)return [];return Object.entries(result.insights.rows).filter(([key,row])=>sceneKeys().includes(key)&&row.used>0&&effective(row)).map(([key,row])=>{const characterId=sceneOwner(key),kind=effective(row);return {key,characterId,kind,amount:row[kind],uses:row.used,encounter:result.name};}).filter(m=>K.character(m.characterId));}
 function record(meta,report){const x=meta.discovery??=fresh(),before=goals.filter(g=>done(x,g.id)).map(g=>g.id),add=(list,k)=>{if(!list.includes(k))list.push(k);};
  for(const r of report.results||[]){
   if(r.winner===0){if(r.practice?.config.control==='auto'&&['attack','protect'].includes(r.autoPolicy))add(x.policies,r.autoPolicy);if(r.traits?.enabled)for(const t of window.CardTraits.summary(r.traits.keys))if(t.level===2&&r.traits.stats[t.id]>0)add(x.traits,t.id);}
   for(const [key,row]of Object.entries(r.insights?.rows||{}))if(rewardKeys().includes(key)&&row.used>0&&effective(row))add(x.rewards,key);
   for(const m of scenes(r)){const old=x.moments.findIndex(a=>a.key===m.key);if(old<0)x.moments.push(m);else if(m.kind===x.moments[old].kind&&m.amount>x.moments[old].amount)x.moments[old]=m;}
  }
  return goals.filter(g=>done(x,g.id)&&!before.includes(g.id)).map(g=>g.id);
 }
 function goalRows(x){return goals.map(g=>({...g,done:done(x,g.id),progress:g.id==='trait'?x.traits.length?x.traits.map(id=>window.CardTraits.traits[id].name).join(' · '):'아직 발동하지 않음':g.id==='policy'?x.policies.length?x.policies.map(id=>id==='attack'?'공격':'보호').join(' · ')+' 승리':'아직 승리 기록 없음':x.rewards.length?x.rewards.length+'종 활용':'아직 효과 기록 없음'}));}
 function moment(m,index=null){const p=P.profile(m.key),amount=Number(m.amount.toFixed(1));return `<article class="discovery-moment">${p.portrait?`<img src="${esc(p.portrait)}" alt="${esc(K.character(m.characterId).name)} 초상화">`:''}<div><small>${esc(K.character(m.characterId).name)} · 대표 기술</small><strong>${esc(D.cards[m.key].name)}</strong><p>“${esc(p.line||'')}”</p><span>${esc(m.encounter)} · 누적 ${labels[m.kind]} ${amount} · 사용 ${m.uses}회</span>${index!==null?`<button data-action="practice-open" data-origin="report" data-result="${index}">같은 조건으로 재전투</button>`:''}</div></article>`;}
 function panel(meta,full=false){const x=meta.discovery||fresh(),rows=goalRows(x),count=rows.filter(g=>g.done).length,next=rows.find(g=>!g.done);return `<section class="panel discovery-panel"><h${full?'2':'3'}>원정에서 발견한 것 <small>${count}/3</small></h${full?'2':'3'}><p class="note">능력치 보상 없이, 다른 구성의 싸우는 모습을 발견하는 목표입니다.</p>${full?`<div class="discovery-goals">${rows.map(g=>`<article><strong>${g.done?'✓ ':''}${g.name}</strong><p>${g.desc}</p><small>${esc(g.progress)}</small></article>`).join('')}</div><h3>기억할 대표 기술</h3><div class="discovery-scenes">${x.moments.length?x.moments.map(m=>moment(m)).join(''):'<p class="note">대표 기술의 실제 피해·회복·보호 효과가 기록되면 기술 기록이 남습니다. 연습은 영구 기록에 포함되지 않습니다.</p>'}</div>`:`${next?`<p><strong>다음 발견 · ${next.name}</strong><br>${next.desc}</p>`:'<p>세 가지 목표를 발견했습니다. 다른 동료·덱·경로의 변화를 비교해보세요.</p>'}<button data-action="archive">발견·대표 기술 살펴보기</button>`}</section>`;}
 function reportPanel(report){const ids=report.discoveries||[],candidates=(report.results||[]).flatMap((r,index)=>scenes(r).map(m=>({...m,index}))),chosen=candidates.sort((a,b)=>b.amount-a.amount)[0];return ids.length||chosen?`<section class="panel discovery-result">${ids.length?`<p class="discovery-new">새로운 발견 · ${ids.map(id=>goals.find(g=>g.id===id)?.name).filter(Boolean).join(' · ')}</p>`:''}${chosen?moment(chosen,chosen.index):''}<p class="note">수치는 해당 교전에서 그 기술이 낸 누적 효과입니다.</p></section>`:'';}
 window.Discovery={fresh,valid,record,goals,goalRows,panel,reportPanel,scenes,validReport:ids=>ids===undefined||unique(ids,goals.map(g=>g.id),3)};
})();
